tool_input.content:
/* level.js — constrói a geometria do nível a partir do grid puro (map.js).
 * 🎨 Render: usa Three.js (CanvasTexture, BufferGeometry, MeshStandardMaterial,
 *            PointLight). Iluminação global vem de engine.js (HemisphereLight +
 *            AmbientLight) — aqui só adiciona um "sol" direcional próprio.
 * Exporta buildLevel(map, THREE) → { group, update, doorMeshes, exitPos, torchLights }.
 */
import { C } from './constants.js';
import * as THREE from 'three';

/* ---------------------------------------------------------------------------
 * Texturas procedurais (canvas 256×256) — padrão DOOM retrô + sujeira/grime.
 * Determinísticas (hash sem Math.random) para QA estável.
 * ------------------------------------------------------------------------- */
const TEX = {
  startan: { base: '#7a2b20', dark: '#4a1510', rivet: '#c96f4a', grime: '#2b0d07', light: '#a85a40' },
  tech:    { base: '#4a5058', dark: '#2b2f36', rivet: '#8a93a0', grime: '#191c21', light: '#b4bcc8' },
  brick:   { base: '#5a2a1e', dark: '#3a1a12', rivet: '#7a4a3a', grime: '#210e08', light: '#8f5a44' },
  emblem:  { base: '#2e3a2e', dark: '#1c241c', rivet: '#7a9a6a', grime: '#0e130e', light: '#a3c088' },
  metal:   { base: '#6a7078', dark: '#3a3e44', rivet: '#a0a8b4', grime: '#1f232a', light: '#cdd5e0' },
  floor:   { base: '#4e545c', dark: '#2e333a', rivet: '#8d959f', grime: '#20242a', light: '#aab4c0' },
  lava:    { base: '#1f0a00', dark: '#0c0300', rivet: '#ff6a1a', grime: '#000000', light: '#ffb066' },
};

/* Hash determinístico 2D → [0,1). Nunca usa Math.random (render estável). */
function hash2(x, y, seed = 1337) {
  let n = ((x | 0) + (y | 0) * 374761393 + (seed | 0) * 668265263) | 0;
  n = ((n ^ (n >>> 13)) * 1274126177) | 0;
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}

/* Passada de grime: mancha levemente pixels determinísticos (sujeira DOOM). */
function grimePass(ctx, w, h, t, strength = 0.07, seed = 7) {
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const r = hash2(x, y, seed);
      if (r > strength) continue;
      const i = (y * w + x) * 4;
      const f = 0.62 + hash2(x, y, seed + 1) * 0.55; // 0.62..1.17
      d[i] = Math.max(0, Math.min(255, d[i] * f));
      d[i + 1] = Math.max(0, Math.min(255, d[i + 1] * f));
      d[i + 2] = Math.max(0, Math.min(255, d[i + 2] * f));
    }
  }
  ctx.putImageData(img, 0, 0);
}

function makeCanvasTexture(name, w = 256, h = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const g = canvas.getContext('2d');
  const t = TEX[name] || TEX.tech;
  g.fillStyle = t.base;
  g.fillRect(0, 0, w, h);

  if (name === 'startan') {
    // painéis verticais com bisel (sombra + realce) + rebites rebaixados
    for (let x = 0; x < w; x += 16) {
      g.fillStyle = t.dark;  g.fillRect(x, 0, 2, h);
      g.fillStyle = t.light; g.fillRect(x + 2, 0, 1, h);
      for (let y = 12; y < h; y += 32) {
        g.fillStyle = t.dark;  g.beginPath(); g.arc(x + 3, y, 2.2, 0, 7); g.fill();
        g.fillStyle = t.light; g.beginPath(); g.arc(x + 2, y - 0.8, 1, 0, 7); g.fill();
      }
    }
    // sujeira acumulada no rodapé + frisos superior/inferior
    const grad = g.createLinearGradient(0, h - 44, 0, h);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.55)');
    g.fillStyle = grad; g.fillRect(0, h - 44, w, 44);
    g.fillStyle = t.rivet; g.fillRect(0, 0, w, 3);
    g.fillStyle = t.dark;  g.fillRect(0, 3, w, 2);
    g.fillStyle = t.dark;  g.fillRect(0, h - 4, w, 4);
  } else if (name === 'tech') {
    // placas 64×64 com junções biseladas + parafusos + linhas de circuito
    for (let py = 0; py < h; py += 64) {
      for (let px = 0; px < w; px += 64) {
        g.fillStyle = t.dark;
        g.fillRect(px + 2, py + 2, 60, 60);
        g.fillStyle = t.light; g.fillRect(px + 1, py + 1, 62, 2);
        g.fillStyle = t.light; g.fillRect(px + 1, py + 1, 2, 62);
        g.fillStyle = t.grime; g.fillRect(px + 1, py + 61, 62, 2);
        g.fillStyle = t.grime; g.fillRect(px + 61, py + 1, 2, 62);
        for (const [sx, sy] of [[6, 6], [58, 6], [6, 58], [58, 58]]) {
          g.fillStyle = t.rivet;
          g.beginPath(); g.arc(px + sx, py + sy, 2.6, 0, 7); g.fill();
          g.strokeStyle = t.dark; g.lineWidth = 1;
          g.beginPath(); g.moveTo(px + sx - 1.6, py + sy - 1.6); g.lineTo(px + sx + 1.6, py + sy + 1.6); g.stroke();
        }
      }
    }
    // linhas de circuito (combinam com o emissive do material)
    g.strokeStyle = t.light; g.lineWidth = 1.5; g.globalAlpha = 0.85;
    for (let k = 0; k < 7; k++) {
      const x0 = hash2(k, 0, 11) * w, y0 = hash2(k, 1, 11) * h;
      const x1 = hash2(k, 2, 11) * w, y1 = hash2(k, 3, 11) * h;
      const mx = (x0 + x1) / 2 + (hash2(k, 4, 11) - 0.5) * 80;
      g.beginPath(); g.moveTo(x0, y0);
      g.lineTo(mx, y0); g.lineTo(mx, y1); g.lineTo(x1, y1);
      g.stroke();
    }
    g.globalAlpha = 1;
  } else if (name === 'brick') {
    // tijolos 32×16 com argamassa biselada, variação por tijolo e lascas
    for (let y = 0; y < h; y += 16) {
      const off = ((y / 16) % 2) * 16;
      for (let x = -16; x < w; x += 32) {
        const bx = x + off;
        g.fillStyle = t.grime; g.fillRect(bx, y, 32, 3);
        g.fillStyle = t.grime; g.fillRect(bx, y, 2, 16);
        const tint = hash2(bx / 32, y / 16, 3);
        g.fillStyle = tint < 0.25 ? t.dark : tint > 0.8 ? t.light : t.base;
        g.fillRect(bx + 2, y + 3, 30, 13);
        g.fillStyle = t.light; g.globalAlpha = 0.4; g.fillRect(bx + 2, y + 3, 30, 1); g.globalAlpha = 1;
        if (hash2(bx, y, 9) < 0.18) {
          const cxm = bx + 6 + hash2(bx, y, 10) * 20;
          g.fillStyle = t.grime;
          g.fillRect(cxm, y + 3, 3 + hash2(bx, y, 11) * 4, 3);
        }
      }
    }
  } else if (name === 'emblem') {
    // painel escuro com vinheta + emblema central com profundidade + arranhões
    const vg = g.createRadialGradient(w / 2, h / 2, 40, w / 2, h / 2, 140);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(0,0,0,0.5)');
    g.fillStyle = vg; g.fillRect(0, 0, w, h);
    g.strokeStyle = t.dark; g.lineWidth = 5; g.strokeRect(4, 4, w - 8, h - 8);
    g.strokeStyle = t.light; g.lineWidth = 2; g.strokeRect(7, 7, w - 14, h - 14);
    // losango com relevo (base escura + face clara + miolo escuro)
    g.fillStyle = t.rivet;
    g.beginPath(); g.moveTo(w / 2, 44); g.lineTo(w - 56, h / 2); g.lineTo(w / 2, h - 44); g.lineTo(56, h / 2); g.closePath(); g.fill();
    g.fillStyle = t.dark;
    g.beginPath(); g.moveTo(w / 2, 52); g.lineTo(w - 62, h / 2); g.lineTo(w / 2, h - 52); g.lineTo(62, h / 2); g.closePath(); g.fill();
    g.fillStyle = t.light;
    g.beginPath(); g.moveTo(w / 2, 48); g.lineTo(w - 58, h / 2); g.lineTo(w / 2, h - 48); g.lineTo(58, h / 2); g.closePath(); g.fill();
    // círculo central
    g.fillStyle = t.rivet;
    g.beginPath(); g.arc(w / 2, h / 2, 22, 0, 7); g.fill();
    g.fillStyle = t.grime;
    g.beginPath(); g.arc(w / 2, h / 2, 16, 0, 7); g.fill();
    // arranhões determinísticos
    g.strokeStyle = t.light; g.lineWidth = 1; g.globalAlpha = 0.5;
    for (let k = 0; k < 6; k++) {
      const ax = hash2(k, 0, 21) * w, ay = hash2(k, 1, 21) * h;
      g.beginPath(); g.moveTo(ax, ay);
      g.lineTo(ax + (hash2(k, 2, 21) - 0.5) * 26, ay + (hash2(k, 3, 21) - 0.5) * 26);
      g.stroke();
    }
    g.globalAlpha = 1;
    g.fillStyle = t.rivet;
    for (const [sx, sy] of [[10, 10], [w - 10, 10], [10, h - 10], [w - 10, h - 10]]) {
      g.beginPath(); g.arc(sx, sy, 2.6, 0, 7); g.fill();
    }
  } else if (name === 'metal') {
    // faixas horizontais com bisel + rebites + arranhões
    for (let y = 0; y < h; y += 32) {
      g.fillStyle = t.dark;  g.fillRect(0, y, w, 2);
      g.fillStyle = t.light; g.fillRect(0, y + 2, w, 1);
      for (let x = 16; x < w; x += 48) {
        g.fillStyle = t.dark;  g.beginPath(); g.arc(x, y + 8, 2, 0, 7); g.fill();
        g.fillStyle = t.light; g.beginPath(); g.arc(x - 0.8, y + 7, 0.9, 0, 7); g.fill();
      }
    }
    g.strokeStyle = t.light; g.lineWidth = 1; g.globalAlpha = 0.45;
    for (let k = 0; k < 9; k++) {
      const ax = hash2(k, 0, 31) * w, ay = hash2(k, 1, 31) * h;
      g.beginPath(); g.moveTo(ax, ay);
      g.lineTo(ax + (hash2(k, 2, 31) - 0.5) * 56, ay + (hash2(k, 3, 31) - 0.5) * 20);
      g.stroke();
    }
    g.globalAlpha = 1;
  } else if (name === 'floor') {
    // grade metálica: placas 32×32 com junções, variação por placa e parafuso
    for (let py = 0; py < h; py += 32) {
      for (let px = 0; px < w; px += 32) {
        const tint = hash2(px / 32, py / 32, 5);
        g.fillStyle = tint < 0.3 ? t.dark : tint > 0.85 ? t.light : t.base;
        g.fillRect(px, py, 32, 32);
        g.fillStyle = t.grime; g.fillRect(px, py, 32, 3);
        g.fillStyle = t.grime; g.fillRect(px, py, 3, 32);
        g.fillStyle = t.light; g.globalAlpha = 0.35;
        g.fillRect(px + 3, py + 3, 29, 1); g.fillRect(px + 3, py + 3, 1, 29);
        g.globalAlpha = 1;
        g.fillStyle = t.dark;  g.beginPath(); g.arc(px + 16, py + 16, 2.4, 0, 7); g.fill();
        g.fillStyle = t.rivet; g.beginPath(); g.arc(px + 16, py + 16, 1.1, 0, 7); g.fill();
      }
    }
  } else if (name === 'lava') {
    // crosta escura + bolhas incandescentes + fendas (tudo determinístico)
    g.fillStyle = t.dark; g.fillRect(0, 0, w, h);
    for (let k = 0; k < 14; k++) {
      const lx = hash2(k, 0, 41) * w, ly = hash2(k, 1, 41) * h;
      const r = 10 + hash2(k, 2, 41) * 26;
      const grad = g.createRadialGradient(lx, ly, 1, lx, ly, r);
      grad.addColorStop(0, 'rgba(255,120,30,0.95)');
      grad.addColorStop(0.55, 'rgba(255,80,10,0.55)');
      grad.addColorStop(1, 'rgba(255,40,0,0)');
      g.fillStyle = grad;
      g.beginPath(); g.arc(lx, ly, r, 0, 7); g.fill();
    }
    g.strokeStyle = 'rgba(255,90,10,0.6)'; g.lineWidth = 1.5;
    for (let k = 0; k < 6; k++) {
      const ax = hash2(k, 0, 43) * w, ay = hash2(k, 1, 43) * h;
      g.beginPath(); g.moveTo(ax, ay);
      g.lineTo(ax + (hash2(k, 2, 43) - 0.5) * 70, ay + (hash2(k, 3, 43) - 0.5) * 70);
      g.stroke();
    }
  }
  grimePass(g, w, h, t);

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.NearestFilter; // retrô: pixelado
  return tex;
}

/* ---------------------------------------------------------------------------
 * Bump maps procedurais (256×256 grayscale) — relevo sem normalMap/tangentes.
 * Mesma estrutura das texturas coloridas (biséis = alto, vincos = baixo).
 * ------------------------------------------------------------------------- */
function makeBumpCanvas(name, w = 256, h = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const g = canvas.getContext('2d');
  const hi = '#e8e8e8', lo = '#282828';
  g.fillStyle = '#808080';
  g.fillRect(0, 0, w, h);

  if (name === 'startan') {
    for (let x = 0; x < w; x += 16) {
      g.fillStyle = lo; g.fillRect(x, 0, 2, h);
      g.fillStyle = hi; g.fillRect(x + 2, 0, 1, h);
      for (let y = 12; y < h; y += 32) {
        g.fillStyle = lo; g.beginPath(); g.arc(x + 3, y, 2, 0, 7); g.fill();
      }
    }
    g.fillStyle = lo; g.fillRect(0, h - 4, w, 4);
    g.fillStyle = hi; g.fillRect(0, 0, w, 2);
  } else if (name === 'tech') {
    for (let py = 0; py < h; py += 64) {
      for (let px = 0; px < w; px += 64) {
        g.fillStyle = lo; g.fillRect(px + 1, py + 1, 62, 62);
        g.fillStyle = hi; g.fillRect(px + 1, py + 1, 62, 2);
        g.fillStyle = hi; g.fillRect(px + 1, py + 1, 2, 62);
        g.fillStyle = lo; g.fillRect(px + 1, py + 61, 62, 2);
        g.fillStyle = lo; g.fillRect(px + 61, py + 1, 2, 62);
        for (const [sx, sy] of [[6, 6], [58, 6], [6, 58], [58, 58]]) {
          g.fillStyle = hi; g.beginPath(); g.arc(px + sx, py + sy, 2, 0, 7); g.fill();
        }
      }
    }
  } else if (name === 'brick') {
    for (let y = 0; y < h; y += 16) {
      const off = ((y / 16) % 2) * 16;
      for (let x = -16; x < w; x += 32) {
        const bx = x + off;
        g.fillStyle = lo; g.fillRect(bx, y, 32, 3);
        g.fillStyle = lo; g.fillRect(bx, y, 2, 16);
        g.fillStyle = hi; g.fillRect(bx + 2, y + 3, 30, 1);
      }
    }
  } else if (name === 'metal') {
    for (let y = 0; y < h; y += 32) {
      g.fillStyle = lo; g.fillRect(0, y, w, 2);
      g.fillStyle = hi; g.fillRect(0, y + 2, w, 1);
      for (let x = 16; x < w; x += 48) {
        g.fillStyle = lo; g.beginPath(); g.arc(x, y + 8, 2, 0, 7); g.fill();
      }
    }
  } else if (name === 'emblem') {
    g.strokeStyle = lo; g.lineWidth = 5; g.strokeRect(4, 4, w - 8, h - 8);
    g.strokeStyle = hi; g.lineWidth = 2; g.strokeRect(7, 7, w - 14, h - 14);
    g.fillStyle = hi;
    g.beginPath(); g.moveTo(w / 2, 44); g.lineTo(w - 56, h / 2); g.lineTo(w / 2, h - 44); g.lineTo(56, h / 2); g.closePath(); g.fill();
    g.fillStyle = lo;
    g.beginPath(); g.arc(w / 2, h / 2, 20, 0, 7); g.fill();
  } else if (name === 'floor') {
    for (let py = 0; py < h; py += 32) {
      for (let px = 0; px < w; px += 32) {
        g.fillStyle = lo; g.fillRect(px, py, 32, 3);
        g.fillStyle = lo; g.fillRect(px, py, 3, 32);
        g.fillStyle = hi; g.fillRect(px + 3, py + 3, 29, 1);
        g.fillStyle = hi; g.fillRect(px + 3, py + 3, 1, 29);
        g.fillStyle = lo; g.beginPath(); g.arc(px + 16, py + 16, 2.4, 0, 7); g.fill();
      }
    }
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.NearestFilter;
  return tex;
}

/* Cache de texturas (uma por tipo). */
const texCache = new Map();
function getTexture(name) {
  if (!texCache.has(name)) texCache.set(name, makeCanvasTexture(name));
  return texCache.get(name);
}

const bumpCache = new Map();
function getBump(name) {
  if (!bumpCache.has(name)) bumpCache.set(name, makeBumpCanvas(name));
  return bumpCache.get(name);
}

/* Materiais iluminados (MeshStandardMaterial) — respondem às luzes globais
 * de engine.js (HemisphereLight + AmbientLight) + ao sol direcional local. */
function wallMaterial(name) {
  const mat = new THREE.MeshStandardMaterial({
    map: getTexture(name),
    bumpMap: getBump(name),
    bumpScale: name === 'brick' ? 0.5 : 0.35,
    roughness: 0.94,
    metalness: 0.1,
  });
  // brilho leve nos painéis tech (linhas de circuito "acesas")
  if (name === 'tech') {
    mat.emissive = new THREE.Color(0x2a3a4a);
    mat.emissiveIntensity = 0.35;
  }
  return mat;
}

/* ---------------------------------------------------------------------------
 * Acumulador de quads → BufferGeometry indexada (faces com normais + UV).
 * ------------------------------------------------------------------------- */
class QuadBuilder {
  constructor() {
    this.pos = [];
    this.nrm = [];
    this.uv = [];
    this.idx = [];
  }
  /* Adiciona um quad vertical (parede): centro (cx,cz), largura dw, altura dh,
   * y-base by, normal (nx,nz) e uv-variante face (0..1). */
  quad(cx, cz, dw, dh, by, nx, nz, v) {
    const i = this.pos.length / 3;
    const hw = dw / 2;
    // face frontal orientada pela normal
    const tx = -nz, tz = nx; // tangente
    const p = [
      cx - tx * hw, by,     cz - tz * hw,
      cx + tx * hw, by,     cz + tz * hw,
      cx + tx * hw, by + dh, cz + tz * hw,
      cx - tx * hw, by + dh, cz - tz * hw,
    ];
    this.pos.push(...p);
    for (let k = 0; k < 4; k++) this.nrm.push(nx, 0, nz);
    // UVs: face vertical divide a textura em 4 faixas (v) — melhor variedade
    const u0 = 0, u1 = dw, v0 = v * 0.25, v1 = v0 + 0.25;
    this.uv.push(u0, v0, u1, v0, u1, v1, u0, v1);
    this.idx.push(i, i + 1, i + 2, i, i + 2, i + 3);
  }
  /* Adiciona um quad horizontal (chão/teto): centro (cx,cz), tamanho (w,h),
   * y fixo, normal (0,±1,0), v-face. */
  hquad(cx, cz, w, h, y, ny, v) {
    const i = this.pos.length / 3;
    const hw = w / 2, hh = h / 2;
    this.pos.push(
      cx - hw, y, cz - hh,
      cx + hw, y, cz - hh,
      cx + hw, y, cz + hh,
      cx - hw, y, cz + hh,
    );
    for (let k = 0; k < 4; k++) this.nrm.push(0, ny, 0);
    this.uv.push(0, 0, w, 0, w, h, 0, h);
    this.idx.push(i, i + 1, i + 2, i, i + 2, i + 3);
  }
  build() {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nrm, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setIndex(this.idx);
    return g;
  }
}

/* ---------------------------------------------------------------------------
 * Construtor do nível
 * ------------------------------------------------------------------------- */
export function buildLevel(map, THREE) {
  const L = C.LEVEL;
  const group = new THREE.Group();
  const wallH = L.wallHeight;
  const ceilY = L.ceilingY;

  // "sol" direcional local (não duplica hemi/ambient de engine.js) — dá
  // sombreamento por face para que as paredes ganhem profundidade real.
  const sun = new THREE.DirectionalLight(0xfff2dd, 0.5);
  sun.position.set(40, 90, 25);
  group.add(sun);

  // builders por textura de parede
  const wallBuilders = new Map(); // nome → QuadBuilder
  function wallB(name) {
    if (!wallBuilders.has(name)) wallBuilders.set(name, new QuadBuilder());
    return wallBuilders.get(name);
  }
  const floorB = new QuadBuilder();
  const ceilB = new QuadBuilder();

  const h = map.H, w = map.W;
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      const ch = map.grid[r][c];
      const isWall = ch === '#';
      const cx = c + 0.5, cz = r + 0.5;
      const zname = map.zone(r, c);

      // chão e teto (todos os tipos)
      const ftex = zname === 'arena' ? 'emblem' : zname === 'entrada' ? 'startan' : zname === 'catacumbas' || zname === 'armadilha' ? 'brick' : 'tech';
      const ctex = ftex === 'emblem' ? 'metal' : ftex;
      floorB.hquad(cx, cz, 1, 1, 0, 1, 0);
      ceilB.hquad(cx, cz, 1, 1, ceilY, -1, 0);

      if (isWall) {
        const b = wallB(ftex === 'emblem' ? 'emblem' : ftex);
        const v = (r + c) % 4;
        if (c > 0 && !map.isSolid(r, c - 1)) b.quad(cx - 0.5, cz, 1, wallH, 0, -1, 0, v);          // oeste
        if (c < w - 1 && !map.isSolid(r, c + 1)) b.quad(cx + 0.5, cz, 1, wallH, 0, 1, 0, v);        // leste
        if (r > 0 && !map.isSolid(r - 1, c)) b.quad(cx, cz - 0.5, 1, wallH, 0, 0, -1, v);          // norte
        if (r < h - 1 && !map.isSolid(r + 1, c)) b.quad(cx, cz + 0.5, 1, wallH, 0, 0, 1, v);        // sul
      }
    }
  }

  // monta meshes das paredes (um por textura)
  for (const [name, b] of wallBuilders) {
    const m = new THREE.Mesh(b.build(), wallMaterial(name));
    m.matrixAutoUpdate = false;
    group.add(m);
  }

  // chão + teto (grade metálica no chão; teto escuro de metal)
  const floorMat = new THREE.MeshStandardMaterial({
    map: getTexture('floor'),
    bumpMap: getBump('floor'),
    bumpScale: 0.25,
    roughness: 0.95,
    metalness: 0.18,
    color: 0xbcc2cc,
  });
  group.add(new THREE.Mesh(floorB.build(), floorMat));
  const ceilMat = new THREE.MeshStandardMaterial({
    map: getTexture('metal'),
    bumpMap: getBump('metal'),
    bumpScale: 0.25,
    roughness: 0.96,
    metalness: 0.2,
    color: 0x55555c,
  });
  group.add(new THREE.Mesh(ceilB.build(), ceilMat));

  // ---- portas ---------------------------------------------------------------
  const doorMeshes = [];
  const frameMat = new THREE.MeshStandardMaterial({ color: 0x262a30, roughness: 0.8, metalness: 0.25 });
  const jambGeo = new THREE.BoxGeometry(0.07, L.doorHeight + 0.08, 0.26);
  const headGeo = new THREE.BoxGeometry(1.14, 0.08, 0.26);
  for (const d of map.doors) {
    const geo = new THREE.BoxGeometry(1, L.doorHeight, 0.18);
    const mat = new THREE.MeshStandardMaterial({
      map: getTexture('metal'),
      bumpMap: getBump('metal'),
      bumpScale: 0.3,
      roughness: 0.88,
      metalness: 0.25,
      emissive: new THREE.Color(0x2a6a4a),
      emissiveIntensity: 0,
    });
    const m = new THREE.Mesh(geo, mat);
    m.position.set(d.c + 0.5, L.doorHeight / 2 - 0.02, d.r + 0.5);
    group.add(m);
    doorMeshes.push({ d, mesh: m, mat });
    // moldura visual (não afeta colisão): ombreiras + verga
    const jamL = new THREE.Mesh(jambGeo, frameMat);
    jamL.position.set(d.c + 0.5 - 0.535, (L.doorHeight + 0.08) / 2, d.r + 0.5);
    group.add(jamL);
    const jamR = new THREE.Mesh(jambGeo, frameMat);
    jamR.position.set(d.c + 0.5 + 0.535, (L.doorHeight + 0.08) / 2, d.r + 0.5);
    group.add(jamR);
    const head = new THREE.Mesh(headGeo, frameMat);
    head.position.set(d.c + 0.5, L.doorHeight + 0.04, d.r + 0.5);
    group.add(head);
  }
  // segredos = portas que sobem quando abertas
  for (const s of map.secrets) {
    const geo = new THREE.BoxGeometry(1, L.doorHeight, 0.18);
    const mat = new THREE.MeshStandardMaterial({
      map: getTexture('brick'),
      bumpMap: getBump('brick'),
      bumpScale: 0.5,
      roughness: 0.95,
      metalness: 0.1,
    });
    const m = new THREE.Mesh(geo, mat);
    m.position.set(s.c + 0.5, L.doorHeight / 2 - 0.02, s.r + 0.5);
    group.add(m);
    doorMeshes.push({ d: s, mesh: m, mat, isSecret: true });
  }

  // ---- saída ----------------------------------------------------------------
  let exitPos = null;
  for (const e of map.exits) {
    const px = e.c + 0.5, pz = e.r + 0.5;
    exitPos = { x: px, z: pz };
    // pilar emissivo + plano brilhante virado para o centro da arena
    const pillar = new THREE.Mesh(
      new THREE.CylinderGeometry(0.22, 0.34, 2.6, 10),
      new THREE.MeshBasicMaterial({ color: 0x88ff88 }),
    );
    pillar.position.set(px, 1.3, pz);
    group.add(pillar);
    const glow = new THREE.Mesh(
      new THREE.PlaneGeometry(0.9, 2.6),
      new THREE.MeshBasicMaterial({ color: 0x66ff66, transparent: true, opacity: 0.85 }),
    );
    glow.position.set(px, 1.3, pz + 0.5);
    group.add(glow);
  }

  // ---- lava ----------------------------------------------------------------
  const lavaMats = [];
  const lavaTex = getTexture('lava');
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      if (map.grid[r][c] !== '~') continue;
      const mat = new THREE.MeshStandardMaterial({
        map: lavaTex,
        color: 0xffffff,
        emissive: new THREE.Color(0xff4a00),
        emissiveIntensity: 0.9,
        transparent: true,
        opacity: 0.96,
        roughness: 0.9,
        metalness: 0.0,
      });
      const m = new THREE.Mesh(new THREE.PlaneGeometry(0.96, 0.96), mat);
      m.rotation.x = -Math.PI / 2;
      m.position.set(c + 0.5, 0.02, r + 0.5);
      group.add(m);
      lavaMats.push(mat);
    }
  }

  // ---- tochas (luz pontual + chama) ------------------------------------------
  const torchLights = [];
  let torchIdx = 0;
  for (const t of map.torches) {
    const x = t.x, z = t.z;
    const flame = new THREE.Mesh(
      new THREE.ConeGeometry(0.07, 0.35, 6),
      new THREE.MeshBasicMaterial({ color: 0xffaa33 }),
    );
    flame.position.set(x, 1.75, z);
    group.add(flame);
    // agrupa luzes: compartilha uma única PointLight a cada par (draw calls)
    if (torchLights.length < 6) {
      const light = new THREE.PointLight(0xff8844, 0.9, 9, 1.6);
      light.position.set(x, 1.9, z);
      group.add(light);
      torchLights.push({ light, base: 0.9, phase: torchIdx * 1.7 });
      torchIdx++;
    }
  }

  // ---- update por frame ------------------------------------------------------
  let elapsed = 0;
  function update(dt) {
    elapsed += dt;
    // portas: sobem quando abertas; segredos descem (t: 0 fechada → 1 aberta)
    for (const { d, mesh, mat, isSecret } of doorMeshes) {
      const target = d.open ? 1 : 0;
      d.t += (target - d.t) * Math.min(1, dt * C.LEVEL.doorSpeed);
      const yOpen = L.doorHeight / 2 - 0.02;
      const yClosed = isSecret ? L.doorHeight + 0.5 : yOpen; // segredo fica acima, porta no lugar
      const y = yClosed + (yOpen - yClosed) * d.t;
      mesh.position.y = y;
      mesh.visible = d.t > 0.05;
      // brilho de "aberta" na porta (visual, sem tocar geometria)
      if (mat) mat.emissiveIntensity = d.open ? 0.5 : 0;
    }
    // lava pulsa (emissiveIntensity — luz própria, não precisa de luz externa)
    for (let i = 0; i < lavaMats.length; i++) {
      lavaMats[i].emissiveIntensity = 0.7 + 0.45 * Math.sin(elapsed * 2.2 + i * 1.7);
    }
    // tochas tremeluzem
    for (const tl of torchLights) {
      const n = Math.sin(elapsed * 11 + tl.phase) * 0.5 + Math.sin(elapsed * 23 + tl.phase * 2) * 0.5;
      tl.light.intensity = tl.base * (0.55 + 0.45 * n);
    }
  }

  return { group, update, doorMeshes, exitPos, torchLights };
}

export default { buildLevel, getTexture };

/* level.js — constrói a geometria do nível a partir do grid puro (map.js).
 * 🎨 Render: usa Three.js (CanvasTexture, BufferGeometry, MeshStandardMaterial,
 *            PointLight). Iluminação global vem de engine.js (HemisphereLight +
 *            AmbientLight) — aqui só adiciona um "sol" direcional próprio.
 * Exporta buildLevel(map, THREE) → { group, update, doorMeshes, exitPos, torchLights }.
 */
import { C } from './constants.js';
import * as THREE from 'three';

/* ---------------------------------------------------------------------------
 * Texturas procedurais (canvas 256×256) — padrão DOOM retrô + sujeira/grime.
 * Determinísticas (hash sem Math.random) para QA estável.
 * ------------------------------------------------------------------------- */
const TEX = {
  startan: { base: '#7a2b20', dark: '#4a1510', rivet: '#c96f4a', grime: '#2b0d07', light: '#a85a40' },
  tech:    { base: '#4a5058', dark: '#2b2f36', rivet: '#8a93a0', grime: '#191c21', light: '#b4bcc8' },
  brick:   { base: '#5a2a1e', dark: '#3a1a12', rivet: '#7a4a3a', grime: '#210e08', light: '#8f5a44' },
  emblem:  { base: '#2e3a2e', dark: '#1c241c', rivet: '#7a9a6a', grime: '#0e130e', light: '#a3c088' },
  metal:   { base: '#6a7078', dark: '#3a3e44', rivet: '#a0a8b4', grime: '#1f232a', light: '#cdd5e0' },
  floor:   { base: '#4e545c', dark: '#2e333a', rivet: '#8d959f', grime: '#20242a', light: '#aab4c0' },
  lava:    { base: '#1f0a00', dark: '#0c0300', rivet: '#ff6a1a', grime: '#000000', light: '#ffb066' },
};

/* Hash determinístico 2D → [0,1). Nunca usa Math.random (render estável). */
function hash2(x, y, seed = 1337) {
  let n = ((x | 0) + (y | 0) * 374761393 + (seed | 0) * 668265263) | 0;
  n = ((n ^ (n >>> 13)) * 1274126177) | 0;
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}

/* Passada de grime: mancha levemente pixels determinísticos (sujeira DOOM). */
function grimePass(ctx, w, h, t, strength = 0.07, seed = 7) {
  const img = ctx.getImageData(0, 0, w, h);
  const d = img.data;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const r = hash2(x, y, seed);
      if (r > strength) continue;
      const i = (y * w + x) * 4;
      const f = 0.62 + hash2(x, y, seed + 1) * 0.55; // 0.62..1.17
      d[i] = Math.max(0, Math.min(255, d[i] * f));
      d[i + 1] = Math.max(0, Math.min(255, d[i + 1] * f));
      d[i + 2] = Math.max(0, Math.min(255, d[i + 2] * f));
    }
  }
  ctx.putImageData(img, 0, 0);
}

function makeCanvasTexture(name, w = 256, h = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const g = canvas.getContext('2d');
  const t = TEX[name] || TEX.tech;
  g.fillStyle = t.base;
  g.fillRect(0, 0, w, h);

  if (name === 'startan') {
    // painéis verticais com bisel (sombra + realce) + rebites rebaixados
    for (let x = 0; x < w; x += 16) {
      g.fillStyle = t.dark;  g.fillRect(x, 0, 2, h);
      g.fillStyle = t.light; g.fillRect(x + 2, 0, 1, h);
      for (let y = 12; y < h; y += 32) {
        g.fillStyle = t.dark;  g.beginPath(); g.arc(x + 3, y, 2.2, 0, 7); g.fill();
        g.fillStyle = t.light; g.beginPath(); g.arc(x + 2, y - 0.8, 1, 0, 7); g.fill();
      }
    }
    // sujeira acumulada no rodapé + frisos superior/inferior
    const grad = g.createLinearGradient(0, h - 44, 0, h);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.55)');
    g.fillStyle = grad; g.fillRect(0, h - 44, w, 44);
    g.fillStyle = t.rivet; g.fillRect(0, 0, w, 3);
    g.fillStyle = t.dark;  g.fillRect(0, 3, w, 2);
    g.fillStyle = t.dark;  g.fillRect(0, h - 4, w, 4);
  } else if (name === 'tech') {
    // placas 64×64 com junções biseladas + parafusos + linhas de circuito
    for (let py = 0; py < h; py += 64) {
      for (let px = 0; px < w; px += 64) {
        g.fillStyle = t.dark;
        g.fillRect(px + 2, py + 2, 60, 60);
        g.fillStyle = t.light; g.fillRect(px + 1, py + 1, 62, 2);
        g.fillStyle = t.light; g.fillRect(px + 1, py + 1, 2, 62);
        g.fillStyle = t.grime; g.fillRect(px + 1, py + 61, 62, 2);
        g.fillStyle = t.grime; g.fillRect(px + 61, py + 1, 2, 62);
        for (const [sx, sy] of [[6, 6], [58, 6], [6, 58], [58, 58]]) {
          g.fillStyle = t.rivet;
          g.beginPath(); g.arc(px + sx, py + sy, 2.6, 0, 7); g.fill();
          g.strokeStyle = t.dark; g.lineWidth = 1;
          g.beginPath(); g.moveTo(px + sx - 1.6, py + sy - 1.6); g.lineTo(px + sx + 1.6, py + sy + 1.6); g.stroke();
        }
      }
    }
    // linhas de circuito (combinam com o emissive do material)
    g.strokeStyle = t.light; g.lineWidth = 1.5; g.globalAlpha = 0.85;
    for (let k = 0; k < 7; k++) {
      const x0 = hash2(k, 0, 11) * w, y0 = hash2(k, 1, 11) * h;
      const x1 = hash2(k, 2, 11) * w, y1 = hash2(k, 3, 11) * h;
      const mx = (x0 + x1) / 2 + (hash2(k, 4, 11) - 0.5) * 80;
      g.beginPath(); g.moveTo(x0, y0);
      g.lineTo(mx, y0); g.lineTo(mx, y1); g.lineTo(x1, y1);
      g.stroke();
    }
    g.globalAlpha = 1;
  } else if (name === 'brick') {
    // tijolos 32×16 com argamassa biselada, variação por tijolo e lascas
    for (let y = 0; y < h; y += 16) {
      const off = ((y / 16) % 2) * 16;
      for (let x = -16; x < w; x += 32) {
        const bx = x + off;
        g.fillStyle = t.grime; g.fillRect(bx, y, 32, 3);
        g.fillStyle = t.grime; g.fillRect(bx, y, 2, 16);
        const tint = hash2(bx / 32, y / 16, 3);
        g.fillStyle = tint < 0.25 ? t.dark : tint > 0.8 ? t.light : t.base;
        g.fillRect(bx + 2, y + 3, 30, 13);
        g.fillStyle = t.light; g.globalAlpha = 0.4; g.fillRect(bx + 2, y + 3, 30, 1); g.globalAlpha = 1;
        if (hash2(bx, y, 9) < 0.18) {
          const cxm = bx + 6 + hash2(bx, y, 10) * 20;
          g.fillStyle = t.grime;
          g.fillRect(cxm, y + 3, 3 + hash2(bx, y, 11) * 4, 3);
        }
      }
    }
  } else if (name === 'emblem') {
    // painel escuro com vinheta + emblema central com profundidade + arranhões
    const vg = g.createRadialGradient(w / 2, h / 2, 40, w / 2, h / 2, 140);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(0,0,0,0.5)');
    g.fillStyle = vg; g.fillRect(0, 0, w, h);
    g.strokeStyle = t.dark; g.lineWidth = 5; g.strokeRect(4, 4, w - 8, h - 8);
    g.strokeStyle = t.light; g.lineWidth = 2; g.strokeRect(7, 7, w - 14, h - 14);
    // losango com relevo (base escura + face clara + miolo escuro)
    g.fillStyle = t.rivet;
    g.beginPath(); g.moveTo(w / 2, 44); g.lineTo(w - 56, h / 2); g.lineTo(w / 2, h - 44); g.lineTo(56, h / 2); g.closePath(); g.fill();
    g.fillStyle = t.dark;
    g.beginPath(); g.moveTo(w / 2, 52); g.lineTo(w - 62, h / 2); g.lineTo(w / 2, h - 52); g.lineTo(62, h / 2); g.closePath(); g.fill();
    g.fillStyle = t.light;
    g.beginPath(); g.moveTo(w / 2, 48); g.lineTo(w - 58, h / 2); g.lineTo(w / 2, h - 48); g.lineTo(58, h / 2); g.closePath(); g.fill();
    // círculo central
    g.fillStyle = t.rivet;
    g.beginPath(); g.arc(w / 2, h / 2, 22, 0, 7); g.fill();
    g.fillStyle = t.grime;
    g.beginPath(); g.arc(w / 2, h / 2, 16, 0, 7); g.fill();
    // arranhões determinísticos
    g.strokeStyle = t.light; g.lineWidth = 1; g.globalAlpha = 0.5;
    for (let k = 0; k < 6; k++) {
      const ax = hash2(k, 0, 21) * w, ay = hash2(k, 1, 21) * h;
      g.beginPath(); g.moveTo(ax, ay);
      g.lineTo(ax + (hash2(k, 2, 21) - 0.5) * 26, ay + (hash2(k, 3, 21) - 0.5) * 26);
      g.stroke();
    }
    g.globalAlpha = 1;
    g.fillStyle = t.rivet;
    for (const [sx, sy] of [[10, 10], [w - 10, 10], [10, h - 10], [w - 10, h - 10]]) {
      g.beginPath(); g.arc(sx, sy, 2.6, 0, 7); g.fill();
    }
  } else if (name === 'metal') {
    // faixas horizontais com bisel + rebites + arranhões
    for (let y = 0; y < h; y += 32) {
      g.fillStyle = t.dark;  g.fillRect(0, y, w, 2);
      g.fillStyle = t.light; g.fillRect(0, y + 2, w, 1);
      for (let x = 16; x < w; x += 48) {
        g.fillStyle = t.dark;  g.beginPath(); g.arc(x, y + 8, 2, 0, 7); g.fill();
        g.fillStyle = t.light; g.beginPath(); g.arc(x - 0.8, y + 7, 0.9, 0, 7); g.fill();
      }
    }
    g.strokeStyle = t.light; g.lineWidth = 1; g.globalAlpha = 0.45;
    for (let k = 0; k < 9; k++) {
      const ax = hash2(k, 0, 31) * w, ay = hash2(k, 1, 31) * h;
      g.beginPath(); g.moveTo(ax, ay);
      g.lineTo(ax + (hash2(k, 2, 31) - 0.5) * 56, ay + (hash2(k, 3, 31) - 0.5) * 20);
      g.stroke();
    }
    g.globalAlpha = 1;
  } else if (name === 'floor') {
    // grade metálica: placas 32×32 com junções, variação por placa e parafuso
    for (let py = 0; py < h; py += 32) {
      for (let px = 0; px < w; px += 32) {
        const tint = hash2(px / 32, py / 32, 5);
        g.fillStyle = tint < 0.3 ? t.dark : tint > 0.85 ? t.light : t.base;
        g.fillRect(px, py, 32, 32);
        g.fillStyle = t.grime; g.fillRect(px, py, 32, 3);
        g.fillStyle = t.grime; g.fillRect(px, py, 3, 32);
        g.fillStyle = t.light; g.globalAlpha = 0.35;
        g.fillRect(px + 3, py + 3, 29, 1); g.fillRect(px + 3, py + 3, 1, 29);
        g.globalAlpha = 1;
        g.fillStyle = t.dark;  g.beginPath(); g.arc(px + 16, py + 16, 2.4, 0, 7); g.fill();
        g.fillStyle = t.rivet; g.beginPath(); g.arc(px + 16, py + 16, 1.1, 0, 7); g.fill();
      }
    }
  } else if (name === 'lava') {
    // crosta escura + bolhas incandescentes + fendas (tudo determinístico)
    g.fillStyle = t.dark; g.fillRect(0, 0, w, h);
    for (let k = 0; k < 14; k++) {
      const lx = hash2(k, 0, 41) * w, ly = hash2(k, 1, 41) * h;
      const r = 10 + hash2(k, 2, 41) * 26;
      const grad = g.createRadialGradient(lx, ly, 1, lx, ly, r);
      grad.addColorStop(0, 'rgba(255,120,30,0.95)');
      grad.addColorStop(0.55, 'rgba(255,80,10,0.55)');
      grad.addColorStop(1, 'rgba(255,40,0,0)');
      g.fillStyle = grad;
      g.beginPath(); g.arc(lx, ly, r, 0, 7); g.fill();
    }
    g.strokeStyle = 'rgba(255,90,10,0.6)'; g.lineWidth = 1.5;
    for (let k = 0; k < 6; k++) {
      const ax = hash2(k, 0, 43) * w, ay = hash2(k, 1, 43) * h;
      g.beginPath(); g.moveTo(ax, ay);
      g.lineTo(ax + (hash2(k, 2, 43) - 0.5) * 70, ay + (hash2(k, 3, 43) - 0.5) * 70);
      g.stroke();
    }
  }
  grimePass(g, w, h, t);

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.NearestFilter; // retrô: pixelado
  return tex;
}

/* ---------------------------------------------------------------------------
 * Bump maps procedurais (256×256 grayscale) — relevo sem normalMap/tangentes.
 * Mesma estrutura das texturas coloridas (biséis = alto, vincos = baixo).
 * ------------------------------------------------------------------------- */
function makeBumpCanvas(name, w = 256, h = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const g = canvas.getContext('2d');
  const hi = '#e8e8e8', lo = '#282828';
  g.fillStyle = '#808080';
  g.fillRect(0, 0, w, h);

  if (name === 'startan') {
    for (let x = 0; x < w; x += 16) {
      g.fillStyle = lo; g.fillRect(x, 0, 2, h);
      g.fillStyle = hi; g.fillRect(x + 2, 0, 1, h);
      for (let y = 12; y < h; y += 32) {
        g.fillStyle = lo; g.beginPath(); g.arc(x + 3, y, 2, 0, 7); g.fill();
      }
    }
    g.fillStyle = lo; g.fillRect(0, h - 4, w, 4);
    g.fillStyle = hi; g.fillRect(0, 0, w, 2);
  } else if (name === 'tech') {
    for (let py = 0; py < h; py += 64) {
      for (let px = 0; px < w; px += 64) {
        g.fillStyle = lo; g.fillRect(px + 1, py + 1, 62, 62);
        g.fillStyle = hi; g.fillRect(px + 1, py + 1, 62, 2);
        g.fillStyle = hi; g.fillRect(px + 1, py + 1, 2, 62);
        g.fillStyle = lo; g.fillRect(px + 1, py + 61, 62, 2);
        g.fillStyle = lo; g.fillRect(px + 61, py + 1, 2, 62);
        for (const [sx, sy] of [[6, 6], [58, 6], [6, 58], [58, 58]]) {
          g.fillStyle = hi; g.beginPath(); g.arc(px + sx, py + sy, 2, 0, 7); g.fill();
        }
      }
    }
  } else if (name === 'brick') {
    for (let y = 0; y < h; y += 16) {
      const off = ((y / 16) % 2) * 16;
      for (let x = -16; x < w; x += 32) {
        const bx = x + off;
        g.fillStyle = lo; g.fillRect(bx, y, 32, 3);
        g.fillStyle = lo; g.fillRect(bx, y, 2, 16);
        g.fillStyle = hi; g.fillRect(bx + 2, y + 3, 30, 1);
      }
    }
  } else if (name === 'metal') {
    for (let y = 0; y < h; y += 32) {
      g.fillStyle = lo; g.fillRect(0, y, w, 2);
      g.fillStyle = hi; g.fillRect(0, y + 2, w, 1);
      for (let x = 16; x < w; x += 48) {
        g.fillStyle = lo; g.beginPath(); g.arc(x, y + 8, 2, 0, 7); g.fill();
      }
    }
  } else if (name === 'emblem') {
    g.strokeStyle = lo; g.lineWidth = 5; g.strokeRect(4, 4, w - 8, h - 8);
    g.strokeStyle = hi; g.lineWidth = 2; g.strokeRect(7, 7, w - 14, h - 14);
    g.fillStyle = hi;
    g.beginPath(); g.moveTo(w / 2, 44); g.lineTo(w - 56, h / 2); g.lineTo(w / 2, h - 44); g.lineTo(56, h / 2); g.closePath(); g.fill();
    g.fillStyle = lo;
    g.beginPath(); g.arc(w / 2, h / 2, 20, 0, 7); g.fill();
  } else if (name === 'floor') {
    for (let py = 0; py < h; py += 32) {
      for (let px = 0; px < w; px += 32) {
        g.fillStyle = lo; g.fillRect(px, py, 32, 3);
        g.fillStyle = lo; g.fillRect(px, py, 3, 32);
        g.fillStyle = hi; g.fillRect(px + 3, py + 3, 29, 1);
        g.fillStyle = hi; g.fillRect(px + 3, py + 3, 1, 29);
        g.fillStyle = lo; g.beginPath(); g.arc(px + 16, py + 16, 2.4, 0, 7); g.fill();
      }
    }
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.magFilter = THREE.NearestFilter;
  return tex;
}

/* Cache de texturas (uma por tipo). */
const texCache = new Map();
function getTexture(name) {
  if (!texCache.has(name)) texCache.set(name, makeCanvasTexture(name));
  return texCache.get(name);
}

const bumpCache = new Map();
function getBump(name) {
  if (!bumpCache.has(name)) bumpCache.set(name, makeBumpCanvas(name));
  return bumpCache.get(name);
}

/* Materiais iluminados (MeshStandardMaterial) — respondem às luzes globais
 * de engine.js (HemisphereLight + AmbientLight) + ao sol direcional local. */
function wallMaterial(name) {
  const mat = new THREE.MeshStandardMaterial({
    map: getTexture(name),
    bumpMap: getBump(name),
    bumpScale: name === 'brick' ? 0.5 : 0.35,
    roughness: 0.94,
    metalness: 0.1,
  });
  // brilho leve nos painéis tech (linhas de circuito "acesas")
  if (name === 'tech') {
    mat.emissive = new THREE.Color(0x2a3a4a);
    mat.emissiveIntensity = 0.35;
  }
  return mat;
}

/* ---------------------------------------------------------------------------
 * Acumulador de quads → BufferGeometry indexada (faces com normais + UV).
 * ------------------------------------------------------------------------- */
class QuadBuilder {
  constructor() {
    this.pos = [];
    this.nrm = [];
    this.uv = [];
    this.idx = [];
  }
  /* Adiciona um quad vertical (parede): centro (cx,cz), largura dw, altura dh,
   * y-base by, normal (nx,nz) e uv-variante face (0..1). */
  quad(cx, cz, dw, dh, by, nx, nz, v) {
    const i = this.pos.length / 3;
    const hw = dw / 2;
    // face frontal orientada pela normal
    const tx = -nz, tz = nx; // tangente
    const p = [
      cx - tx * hw, by,     cz - tz * hw,
      cx + tx * hw, by,     cz + tz * hw,
      cx + tx * hw, by + dh, cz + tz * hw,
      cx - tx * hw, by + dh, cz - tz * hw,
    ];
    this.pos.push(...p);
    for (let k = 0; k < 4; k++) this.nrm.push(nx, 0, nz);
    // UVs: face vertical divide a textura em 4 faixas (v) — melhor variedade
    const u0 = 0, u1 = dw, v0 = v * 0.25, v1 = v0 + 0.25;
    this.uv.push(u0, v0, u1, v0, u1, v1, u0, v1);
    this.idx.push(i, i + 1, i + 2, i, i + 2, i + 3);
  }
  /* Adiciona um quad horizontal (chão/teto): centro (cx,cz), tamanho (w,h),
   * y fixo, normal (0,±1,0), v-face. */
  hquad(cx, cz, w, h, y, ny, v) {
    const i = this.pos.length / 3;
    const hw = w / 2, hh = h / 2;
    this.pos.push(
      cx - hw, y, cz - hh,
      cx + hw, y, cz - hh,
      cx + hw, y, cz + hh,
      cx - hw, y, cz + hh,
    );
    for (let k = 0; k < 4; k++) this.nrm.push(0, ny, 0);
    this.uv.push(0, 0, w, 0, w, h, 0, h);
    this.idx.push(i, i + 1, i + 2, i, i + 2, i + 3);
  }
  build() {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nrm, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setIndex(this.idx);
    return g;
  }
}

/* ---------------------------------------------------------------------------
 * Construtor do nível
 * ------------------------------------------------------------------------- */
export function buildLevel(map, THREE) {
  const L = C.LEVEL;
  const group = new THREE.Group();
  const wallH = L.wallHeight;
  const ceilY = L.ceilingY;

  // "sol" direcional local (não duplica hemi/ambient de engine.js) — dá
  // sombreamento por face para que as paredes ganhem profundidade real.
  const sun = new THREE.DirectionalLight(0xfff2dd, 0.5);
  sun.position.set(40, 90, 25);
  group.add(sun);

  // builders por textura de parede
  const wallBuilders = new Map(); // nome → QuadBuilder
  function wallB(name) {
    if (!wallBuilders.has(name)) wallBuilders.set(name, new QuadBuilder());
    return wallBuilders.get(name);
  }
  const floorB = new QuadBuilder();
  const ceilB = new QuadBuilder();

  const h = map.H, w = map.W;
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      const ch = map.grid[r][c];
      const isWall = ch === '#';
      const cx = c + 0.5, cz = r + 0.5;
      const zname = map.zone(r, c);

      // chão e teto (todos os tipos)
      const ftex = zname === 'arena' ? 'emblem' : zname === 'entrada' ? 'startan' : zname === 'catacumbas' || zname === 'armadilha' ? 'brick' : 'tech';
      const ctex = ftex === 'emblem' ? 'metal' : ftex;
      floorB.hquad(cx, cz, 1, 1, 0, 1, 0);
      ceilB.hquad(cx, cz, 1, 1, ceilY, -1, 0);

      if (isWall) {
        const b = wallB(ftex === 'emblem' ? 'emblem' : ftex);
        const v = (r + c) % 4;
        if (c > 0 && !map.isSolid(r, c - 1)) b.quad(cx - 0.5, cz, 1, wallH, 0, -1, 0, v);          // oeste
        if (c < w - 1 && !map.isSolid(r, c + 1)) b.quad(cx + 0.5, cz, 1, wallH, 0, 1, 0, v);        // leste
        if (r > 0 && !map.isSolid(r - 1, c)) b.quad(cx, cz - 0.5, 1, wallH, 0, 0, -1, v);          // norte
        if (r < h - 1 && !map.isSolid(r + 1, c)) b.quad(cx, cz + 0.5, 1, wallH, 0, 0, 1, v);        // sul
      }
    }
  }

  // monta meshes das paredes (um por textura)
  for (const [name, b] of wallBuilders) {
    const m = new THREE.Mesh(b.build(), wallMaterial(name));
    m.matrixAutoUpdate = false;
    group.add(m);
  }

  // chão + teto (grade metálica no chão; teto escuro de metal)
  const floorMat = new THREE.MeshStandardMaterial({
    map: getTexture('floor'),
    bumpMap: getBump('floor'),
    bumpScale: 0.25,
    roughness: 0.95,
    metalness: 0.18,
    color: 0xbcc2cc,
  });
  group.add(new THREE.Mesh(floorB.build(), floorMat));
  const ceilMat = new THREE.MeshStandardMaterial({
    map: getTexture('metal'),
    bumpMap: getBump('metal'),
    bumpScale: 0.25,
    roughness: 0.96,
    metalness: 0.2,
    color: 0x55555c,
  });
  group.add(new THREE.Mesh(ceilB.build(), ceilMat));

  // ---- portas ---------------------------------------------------------------
  const doorMeshes = [];
  const frameMat = new THREE.MeshStandardMaterial({ color: 0x262a30, roughness: 0.8, metalness: 0.25 });
  const jambGeo = new THREE.BoxGeometry(0.07, L.doorHeight + 0.08, 0.26);
  const headGeo = new THREE.BoxGeometry(1.14, 0.08, 0.26);
  for (const d of map.doors) {
    const geo = new THREE.BoxGeometry(1, L.doorHeight, 0.18);
    const mat = new THREE.MeshStandardMaterial({
      map: getTexture('metal'),
      bumpMap: getBump('metal'),
      bumpScale: 0.3,
      roughness: 0.88,
      metalness: 0.25,
      emissive: new THREE.Color(0x2a6a4a),
      emissiveIntensity: 0,
    });
    const m = new THREE.Mesh(geo, mat);
    m.position.set(d.c + 0.5, L.doorHeight / 2 - 0.02, d.r + 0.5);
    group.add(m);
    doorMeshes.push({ d, mesh: m, mat });
    // moldura visual (não afeta colisão): ombreiras + verga
    const jamL = new THREE.Mesh(jambGeo, frameMat);
    jamL.position.set(d.c + 0.5 - 0.535, (L.doorHeight + 0.08) / 2, d.r + 0.5);
    group.add(jamL);
    const jamR = new THREE.Mesh(jambGeo, frameMat);
    jamR.position.set(d.c + 0.5 + 0.535, (L.doorHeight + 0.08) / 2, d.r + 0.5);
    group.add(jamR);
    const head = new THREE.Mesh(headGeo, frameMat);
    head.position.set(d.c + 0.5, L.doorHeight + 0.04, d.r + 0.5);
    group.add(head);
  }
  // segredos = portas que sobem quando abertas
  for (const s of map.secrets) {
    const geo = new THREE.BoxGeometry(1, L.doorHeight, 0.18);
    const mat = new THREE.MeshStandardMaterial({
      map: getTexture('brick'),
      bumpMap: getBump('brick'),
      bumpScale: 0.5,
      roughness: 0.95,
      metalness: 0.1,
    });
    const m = new THREE.Mesh(geo, mat);
    m.position.set(s.c + 0.5, L.doorHeight / 2 - 0.02, s.r + 0.5);
    group.add(m);
    doorMeshes.push({ d: s, mesh: m, mat, isSecret: true });
  }

  // ---- saída ----------------------------------------------------------------
  let exitPos = null;
  for (const e of map.exits) {
    const px = e.c + 0.5, pz = e.r + 0.5;
    exitPos = { x: px, z: pz };
    // pilar emissivo + plano brilhante virado para o centro da arena
    const pillar = new THREE.Mesh(
      new THREE.CylinderGeometry(0.22, 0.34, 2.6, 10),
      new THREE.MeshBasicMaterial({ color: 0x88ff88 }),
    );
    pillar.position.set(px, 1.3, pz);
    group.add(pillar);
    const glow = new THREE.Mesh(
      new THREE.PlaneGeometry(0.9, 2.6),
      new THREE.MeshBasicMaterial({ color: 0x66ff66, transparent: true, opacity: 0.85 }),
    );
    glow.position.set(px, 1.3, pz + 0.5);
    group.add(glow);
  }

  // ---- lava ----------------------------------------------------------------
  const lavaMats = [];
  const lavaTex = getTexture('lava');
  for (let r = 0; r < h; r++) {
    for (let c = 0; c < w; c++) {
      if (map.grid[r][c] !== '~') continue;
      const mat = new THREE.MeshStandardMaterial({
        map: lavaTex,
        color: 0xffffff,
        emissive: new THREE.Color(0xff4a00),
        emissiveIntensity: 0.9,
        transparent: true,
        opacity: 0.96,
        roughness: 0.9,
        metalness: 0.0,
      });
      const m = new THREE.Mesh(new THREE.PlaneGeometry(0.96, 0.96), mat);
      m.rotation.x = -Math.PI / 2;
      m.position.set(c + 0.5, 0.02, r + 0.5);
      group.add(m);
      lavaMats.push(mat);
    }
  }

  // ---- tochas (luz pontual + chama) ------------------------------------------
  const torchLights = [];
  let torchIdx = 0;
  for (const t of map.torches) {
    const x = t.x, z = t.z;
    const flame = new THREE.Mesh(
      new THREE.ConeGeometry(0.07, 0.35, 6),
      new THREE.MeshBasicMaterial({ color: 0xffaa33 }),
    );
    flame.position.set(x, 1.75, z);
    group.add(flame);
    // agrupa luzes: compartilha uma única PointLight a cada par (draw calls)
    if (torchLights.length < 6) {
      const light = new THREE.PointLight(0xff8844, 0.9, 9, 1.6);
      light.position.set(x, 1.9, z);
      group.add(light);
      torchLights.push({ light, base: 0.9, phase: torchIdx * 1.7 });
      torchIdx++;
    }
  }

  // ---- update por frame ------------------------------------------------------
  let elapsed = 0;
  function update(dt) {
    elapsed += dt;
    // portas: sobem quando abertas; segredos descem (t: 0 fechada → 1 aberta)
    for (const { d, mesh, mat, isSecret } of doorMeshes) {
      const target = d.open ? 1 : 0;
      d.t += (target - d.t) * Math.min(1, dt * C.LEVEL.doorSpeed);
      const yOpen = L.doorHeight / 2 - 0.02;
      const yClosed = isSecret ? L.doorHeight + 0.5 : yOpen; // segredo fica acima, porta no lugar
      const y = yClosed + (yOpen - yClosed) * d.t;
      mesh.position.y = y;
      mesh.visible = d.t > 0.05;
      // brilho de "aberta" na porta (visual, sem tocar geometria)
      if (mat) mat.emissiveIntensity = d.open ? 0.5 : 0;
    }
    // lava pulsa (emissiveIntensity — luz própria, não precisa de luz externa)
    for (let i = 0; i < lavaMats.length; i++) {
      lavaMats[i].emissiveIntensity = 0.7 + 0.45 * Math.sin(elapsed * 2.2 + i * 1.7);
    }
    // tochas tremeluzem
    for (const tl of torchLights) {
      const n = Math.sin(elapsed * 11 + tl.phase) * 0.5 + Math.sin(elapsed * 23 + tl.phase * 2) * 0.5;
      tl.light.intensity = tl.base * (0.55 + 0.45 * n);
    }
  }

  return { group, update, doorMeshes, exitPos, torchLights };
}

export default { buildLevel, getTexture };

